/**
 * Guarded service-worker registration. The SW (/sw.js, generated by
 * vite-plugin-pwa) must never register in dev or in Lovable preview contexts,
 * where it would keep serving stale HTML after code changes.
 */

const PREVIEW_LABEL = /^(?:id-preview|preview)(?:-[a-z0-9]+)?--.+$/;
const PREVIEW_HOST_SUFFIXES = [".lovable.app", ".gpt-eng.com", ".gptengineer.run"];
const BLOCKED_HOSTS = ["lovableproject.com", "lovableproject-dev.com", "beta.lovable.dev"];

export interface SwEnvironment {
  hostname: string;
  isProd: boolean;
  inIframe: boolean;
  /** URL has ?sw=off (kill switch). */
  swDisabled: boolean;
}

export function shouldRegisterSw(env: SwEnvironment): boolean {
  if (!env.isProd || env.inIframe || env.swDisabled) return false;
  const host = env.hostname.toLowerCase();
  const firstLabel = host.split(".")[0] ?? "";
  if (PREVIEW_HOST_SUFFIXES.some((s) => host.endsWith(s)) && PREVIEW_LABEL.test(firstLabel)) {
    return false;
  }
  if (BLOCKED_HOSTS.some((b) => host === b || host.endsWith(`.${b}`))) return false;
  return true;
}

/** Unregister any existing registration whose script is our /sw.js. */
async function unregisterAppSw(): Promise<void> {
  if (!("serviceWorker" in navigator)) return;
  const regs = await navigator.serviceWorker.getRegistrations();
  await Promise.all(
    regs
      .filter((r) => {
        const url = r.active?.scriptURL ?? r.waiting?.scriptURL ?? r.installing?.scriptURL ?? "";
        return new URL(url, window.location.origin).pathname === "/sw.js";
      })
      .map((r) => r.unregister()),
  );
}

/**
 * Registers the app SW when the context allows it; otherwise removes any
 * stale registration of /sw.js. Call once from a client-only effect.
 */
export async function registerAppSw(): Promise<void> {
  if (typeof window === "undefined" || !("serviceWorker" in navigator)) return;
  const env: SwEnvironment = {
    hostname: window.location.hostname,
    isProd: import.meta.env.PROD,
    inIframe: window.self !== window.top,
    swDisabled: new URLSearchParams(window.location.search).get("sw") === "off",
  };
  if (!shouldRegisterSw(env)) {
    await unregisterAppSw();
    return;
  }
  try {
    await navigator.serviceWorker.register("/sw.js", { scope: "/" });
  } catch (e) {
    console.warn("Não foi possível ativar o modo offline:", e);
  }
}
